        .mat-btn-water { --active-color: var(--water-color); }
        .mat-btn-wall { --active-color: var(--wall-color); }
        .mat-btn-acid { --active-color: var(--acid-color); }
        .mat-btn-empty { --active-color: #555; }

    </style>
</head>
<body>

<div class="sandbox-container">
    <canvas id="sand" width="160" height="160"></canvas>

    <div class="controls">
        <button id="mat-sand" onclick="uiSetMat('sand')">Sand</button>
        <button id="mat-water" onclick="uiSetMat('water')">Water</button>
        <button id="mat-wall" onclick="uiSetMat('wall')">Wall</button>
        <button id="mat-acid" onclick="uiSetMat('acid')">Acid</button>
        <button id="mat-empty" onclick="uiSetMat('empty')">Eraser</button>
        <div style="width: 100%; height: 0;"></div> <!-- Spacer -->
        <button id="clear" onclick="sim.clear()">Clear Grid</button>
    </div>
</div>

<script>
/**
 * CORE SIMULATION ENGINE
 */
class FallingSandSim {
    constructor(w, h) {
        this.w = w;
        this.h = h;
        this.grid = new Int8Array(w * h);
        // 0: empty, 1: sand, 2: water, 3: wall, 4: acid
        this.mats = ["empty", "sand", "water", "wall", "acid"];
    }

    get(x, y) {
        if (x < 0 || x >= this.w || y < 0 || y >= this.h) return null;
        return this.mats[this.grid[y * this.w + x]];
    }

    set(x, y, materialName) {
        if (x < 0 || x >= this.w || y < 0 || y >= this.h) return;
        const idx = this.mats.indexOf(materialName);
        if (idx !== -1) this.grid[y * this.w + x] = idx;
    }

    clear() {
        this.grid.fill(0);
    }

    tick(n = 1) {
        for (let step = 0; step < n; step++) {
            // Process bottom-to-top to prevent single-frame teleportation/anti-gravity
            for (let y = this.h - 2; y >= 0; y--) {
                const xOrder = Math.random() > 0.5 ? 
                    Array.from({length: this.w}, (_, i) => i) : 
                    Array.from({length: this.w}, (_, i) => (this.w - 1) - i);

                for (let x of xOrder) {
                    const idx = y * this.w + x;
                    const type = this.grid[idx];
                    if (type === 0 || type === 3) continue; // Skip empty and wall

                    if (type === 1) this._handleSand(x, y);
                    else if (type === 2 || type === 4) this._handleLiquid(x, y, type);
                }
            }
        }
    }

    _isBounds(x, y) {
        return x >= 0 && x < this.w && y >= 0 && y < this.h;
    }

    _handleSand(x, y) {
        const downY = y + 1;
        const belowIdx = downY * this.w + x;
        const currIdx = y * this.w + x;

        // Try moving straight down
        if (this._isBounds(x, downY)) {
            const target = this.grid[belowIdx];
            if (target === 0 || target === 2 || target === 4) {
                this.grid[belowIdx] = 1;
                this.grid[currIdx] = target; // swap with liquid or empty
                return;
            }
        }

        // Try diagonals
        const dirs = Math.random() > 0.5 ? [[-1, 1], [1, 1]] : [[1, 1], [-1, 1]];
        for (let [dx, dy] of dirs) {
            const nx = x + dx, ny = y + dy;
            if (this._isBounds(nx, ny)) {
                const targetIdx = ny * this.w + nx;
                const target = this.grid[targetIdx];
                if (target === 0 || target === 2 || target === 4) {
                    this.grid[targetIdx] = 1;
                    this.grid[currIdx] = target;
                    return;
                }
            }
        }
    }

    _handleLiquid(x, y, type) {
        // Order: Down, then Diagonals, then Horizontal
        const dirs = [[0, 1], [-1, 1], [1, 1], [-1, 0], [1, 0]];
        const currIdx = y * this.w + x;

        for (let [dx, dy] of dirs) {
            const nx = x + dx, ny = y + dy;
            if (!this._isBounds(nx, ny)) continue;

            const targetIdx = ny * this.w + nx;
            const targetType = this.grid[targetIdx];

            // Acid Dissolution logic
            if (type === 4 && (targetType === 1 || targetType === 3)) {
                this.grid[targetIdx] = 0;
                this.grid[currIdx] = 0; // Acid also disappears during reaction
                return;
            }

            // Movement logic: Move into empty, or swap with other liquid
            if (targetType === 0 || (type !== targetType && targetType !== 1 && targetType !== 3)) {
                // If it's a swap between liquids (e.g. water and acid), allow movement
                this.grid[targetIdx] = type;
                this.grid[currIdx] = targetType;
                return;
            }
        }
    }
}

/**
 * UI & RENDERING LOGIC
 */
const W = 160, H = 160;
const canvas = document.getElementById('sand');
const ctx = canvas.getContext('2d', { alpha: false });
const sim = new FallingSandSim(W, H);

// Expose to window for grading
window.sim = sim;

let activeMat = 'sand';

function uiSetMat(m) {
    activeMat = m;
    document.querySelectorAll('.controls button').forEach(b => b.classList.remove('active'));
    const btn = document.getElementById(`mat-${m}`);
    if (btn) btn.classList.add('active');
}
uiSetMat('sand');

// Input Interaction
let isMouseDown = false;
function handlePointer(e) {
    const rect = canvas.getBoundingClientRect();
    const scaleX = canvas.width / rect.width;
    const scaleY = canvas.height / rect.height;
    const x = Math.floor((e.clientX - rect.left) * scaleX);
    const y = Math.floor((e.clientY - rect.top) * scaleY);

    // Brush size 2x2
    for (let dy = -1; dy <= 0; dy++) {
        for (let dx = -1; dx <= 0; dx++) {
            sim.set(x + dx, y + dy, activeMat);
        }
    }
}

canvas.addEventListener('mousedown', (e) => { isMouseDown = true; handlePointer(e); });
window.addEventListener('mouseup', () => { isMouseDown = false; });
canvas.addEventListener('mousemove', (e) => { if (isMouseDown) handlePointer(e); });

// Rendering loop
const colorMap = { 0: '#000000', 1: '#f4d03f', 2: '#3498db', 3: '#7f8c8d', 4: '#2ecc71' };

function render() {
    // Advance simulation
    sim.tick(1);

    // Draw
    ctx.fillStyle = '#000';
    ctx.fillRect(0, 0, W, H);

    for (let y = 0; y < H; y++) {
        for (let x = 0; x < W; x++) {
            const type = sim.grid[y * W + x];
            if (type !== 0) {
                ctx.fillStyle = colorMap[type];
                ctx.fillRect(x, y, 1, 1);
            }
        }
    }

    requestAnimationFrame(render);
}

// Start Loop
requestAnimationFrame(render);
</script>

</body>
</html>
